#!/usr/bin/env python3
"""Exercise the actual local GLB hierarchy without a browser. Uses pinned three.js
in an isolated temporary directory; leaves the no-build web project untouched.
"""
from pathlib import Path
import os, subprocess, tempfile
ROOT = Path(__file__).resolve().parents[2]
CHECK = "import fs from 'node:fs';\nimport * as THREE from 'three';\nconst workspace=process.env.ROUGAROU_ROOT;\nconst {Skin}=await import(workspace+'/web/skin.js');\nconst {walkPose,solve}=await import(workspace+'/web/climber.js');\nconst {Vec3}=await import(workspace+'/web/sim.js');\nconst dir=workspace+'/web/';\nconst {measure,reach}=await import(workspace+'/web/human-motion.js');\nconst buffer=fs.readFileSync(dir+'models/corey-player.glb');const json=JSON.parse(buffer.subarray(20,20+buffer.readUInt32LE(12)).toString());\nconst joints=new Set(json.skins.flatMap(s=>s.joints));\nconst nodes=json.nodes.map((n,i)=>{const b=joints.has(i)?new THREE.Bone():new THREE.Object3D();b.name=n.name||'';if(n.translation)b.position.fromArray(n.translation);if(n.rotation)b.quaternion.fromArray(n.rotation);if(n.scale)b.scale.fromArray(n.scale);if(n.matrix){b.matrix.fromArray(n.matrix);b.matrix.decompose(b.position,b.quaternion,b.scale);}return b;});\njson.nodes.forEach((n,i)=>n.children?.forEach(c=>nodes[i].add(nodes[c])));const root=new THREE.Group();json.scenes[json.scene||0].nodes.forEach(i=>root.add(nodes[i]));\nconst scene=new THREE.Scene(),profile=JSON.parse(fs.readFileSync(dir+'human-motion.json'));const skin=new Skin({scene:root},scene,profile);\nlet maxMove=0,previous=new Map();\nfor(let i=0;i<240;i++) {\n const pose=solve(walkPose({at:new Vec3(),yaw:i/240,amp:i<180?1:0,phase:i*.1},i/60));\n skin.pose(pose,1/60,true);\n skin.garments.offsets.forEach((o,i)=>{if(!o.toArray().every(Number.isFinite)||o.length()>(i<4?.045:i<6?.02:.025)+1e-6)throw Error('unbounded cloth');});\n for(const b of skin.order){\n if(skin.motion.bounds.has(b)){const m=measure(skin.motion.neutral.get(b).clone().invert().multiply(b.quaternion),skin.motion.frames.get(b)),lim=skin.motion.bounds.get(b);if(m.theta>reach(lim,m.phi*Math.PI/180)+.02||m.twist<lim.twist[0]-.02||m.twist>lim.twist[1]+.02)throw Error('joint limit '+b.name);}\n if(![...b.position,...b.quaternion].every(Number.isFinite))throw Error('nonfinite '+b.name);if(b.name!=='Hips'&&!['HemFront','HemBack','HemLeft','HemRight','SleeveLeft','SleeveRight','CuffLeft','CuffRight'].includes(b.name)&&b.position.distanceTo(skin.restLocal.get(b).p)>1e-6)throw Error('changed bone length '+b.name);if(previous.has(b))maxMove=Math.max(maxMove,previous.get(b).angleTo(b.quaternion));previous.set(b,b.quaternion.clone());}\n}\nif(maxMove>8/60+.001)throw Error('joint discontinuity '+maxMove);\nconst result={bones:skin.order.length,boundedJoints:skin.motion.bounds.size,frames:240,maxFrameRotation:maxMove};\nfs.mkdirSync(workspace+'/unreal/Saved/HumanMotion',{recursive:true});fs.writeFileSync(workspace+'/unreal/Saved/HumanMotion/web-validation.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));\n"
LOADER = "export async function resolve(specifier,context,nextResolve){if(specifier==='three')return {url:'file://TEMP_PATH/node_modules/three/build/three.module.js',shortCircuit:true};if(specifier.startsWith('three/addons/'))return {url:'file://TEMP_PATH/node_modules/three/examples/jsm/'+specifier.slice(13),shortCircuit:true};return nextResolve(specifier,context);}\n"
with tempfile.TemporaryDirectory(prefix="rougarou-motion-") as directory:
    task = Path(directory)
    subprocess.run(["npm", "install", "--prefix", directory, "three@0.169.0", "--no-audit", "--no-fund"], check=True, stdout=subprocess.DEVNULL)
    (task / "check.mjs").write_text(CHECK)
    (task / "loader.mjs").write_text(LOADER.replace("TEMP_PATH", task.as_posix()))
    env = dict(os.environ, ROUGAROU_ROOT=str(ROOT))
    subprocess.run(["node", "--no-warnings", "--experimental-loader=" + str(task / "loader.mjs"), str(task / "check.mjs")], check=True, env=env)
